INSERT INTO categories (id, slug, name, description, sort_order) VALUES (1, 't-shirts', 'T-Shirts', 'Short and long sleeve blanks for everyday custom prints.', 1);
INSERT INTO categories (id, slug, name, description, sort_order) VALUES (2, 'polo-shirts', 'Polo Shirts', 'Collared polos ready for teams, uniforms and custom prints.', 2);
INSERT INTO categories (id, slug, name, description, sort_order) VALUES (3, 'sweatshirts', 'Sweatshirts', 'Fleece layers built for bold, durable custom prints.', 3);
INSERT INTO categories (id, slug, name, description, sort_order) VALUES (4, 'accessories', 'Accessories', 'Caps, totes and mugs that carry your brand beyond the tee.', 4);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (1, 'crown-classic-tee', 'Crown Classic Tee', 'RT2000', 1, 'tee', 'customizable', 'The everyday unisex tee — soft midweight cotton that takes a full front or back print without stiffening.', 'The blank we print most. A midweight 100% cotton body with shoulder-to-shoulder taping keeps the collar flat through repeated washes, and the side-seamed construction gives artwork a flat surface on the front, back, left chest or both sides. It holds a large back print without the ink sitting heavy on the surface.', '100% cotton, 5.3 oz / 180 gsm, unisex fit', 9.5, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 1, 1, 1);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (2, 'heavy-cotton-tee', 'Heavy Cotton Tee', 'G500', 1, 'tee', 'customizable', 'A denser cotton tee built for bold, high-coverage prints.', 'Substantial cotton with a roomy cut and a dry hand. The heavier knit stands up to large, high-coverage prints and holds its shape over a long run, which makes it a favourite for team and event tees.', '100% cotton, 5.3 oz / 180 gsm, heavyweight', 9, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 1, 1, 2);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (3, 'softstyle-tee', 'Softstyle Tee', 'G640', 1, 'tee', 'customizable', 'A lighter ring-spun tee with a smooth face that keeps fine detail sharp.', 'Ring-spun cotton removes loose fibres, so fine linework and small text reproduce cleanly. The lighter weight makes it a natural choice for detail-heavy artwork and retail-style merch.', '100% ring-spun cotton, 4.5 oz / 153 gsm', 10, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 1, 1, 3);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (4, 'ultra-cotton-tee', 'Ultra Cotton Tee', 'G200', 1, 'tee', 'customizable', 'The classic workhorse blank: substantial cotton with a relaxed, roomy cut.', 'A thick, sturdy cotton tee with plenty of room through the body. It takes heavy ink coverage well and is the blank we reach for when a print needs to feel substantial on the garment.', '100% cotton, 6.0 oz / 203 gsm', 9.75, 11.5, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 4);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (5, 'comfort-colors-tee', 'Comfort Colors Tee', 'C1717', 1, 'tee', 'customizable', 'Garment-dyed cotton with a lived-in colour and a soft, broken-in hand.', 'Garment dyeing gives every piece a slightly faded, vintage tone and a soft hand straight out of the box. The muted palette prints beautifully with both light and dark ink, and the heavier body drapes well.', '100% garment-dyed cotton, 6.1 oz / 207 gsm', 13.5, NULL, 5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 1, 1, 5);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (6, 'tri-blend-tee', 'Tri-Blend Tee', '3413C', 1, 'tee', 'customizable', 'Cotton, polyester and rayon for an exceptionally soft, drapey tee.', 'The softest blank in the range. The tri-blend knit has a subtle heathered look and a fluid drape that suits retail-style designs and smaller, centred prints.', '50% poly / 25% cotton / 25% rayon, 3.8 oz', 14.25, NULL, 5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 1, 1, 6);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (7, 'cvc-tee', 'CVC Cotton Blend Tee', 'N6210', 1, 'tee', 'customizable', 'A cotton/poly blend that resists shrinking and holds colour wash after wash.', 'The cotton/poly blend keeps its size and colour far better than a pure cotton tee, which makes it a strong pick for uniforms and repeated wear. Soft enough for retail, durable enough for a work crew.', '60% cotton / 40% polyester, 4.3 oz', 11.5, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 7);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (8, 'performance-tee', 'Performance Tee', 'N3142', 1, 'tee', 'customizable', 'Moisture-wicking polyester for team kits, gyms and outdoor events.', 'A light, quick-drying performance knit that pulls moisture away from the body. Built for sports teams, gyms and outdoor events where a cotton tee would hold sweat.', '100% polyester, 3.8 oz, moisture-wicking', 12, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 8);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (9, 'pocket-tee', 'Heavyweight Pocket Tee', '6030CC', 1, 'tee', 'customizable', 'Garment-dyed cotton with a chest pocket and a relaxed cut.', 'A garment-dyed heavyweight with a functional chest pocket and a relaxed, boxy cut. The pocket gives small left-chest marks a natural anchor point.', '100% garment-dyed cotton, 6.1 oz, chest pocket', 14, NULL, 5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 9);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (10, 'heather-cvc-tee', 'Heather CVC Tee', '3001CVC', 1, 'tee', 'customizable', 'A soft heather blend with a subtle texture that hides creases.', 'The heathered knit has a light texture that masks creases and prints with a soft, matte finish. A versatile middle ground between a cotton tee and a performance shirt.', '52% cotton / 48% polyester, 4.2 oz', 12.5, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 10);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (11, 'womens-fitted-tee', 'Women''s Fitted Tee', 'G640L', 1, 'tee', 'customizable', 'A tapered, side-seamed cut with a contoured fit.', 'Cut and sewn for a contoured fit with shorter sleeves and a tapered waist. The ring-spun cotton keeps the surface smooth so detailed prints stay crisp.', '100% ring-spun cotton, 4.5 oz, women''s fit', 10.5, NULL, 4.5, '{"frontW":0.4,"frontH":0.48,"backW":0.58,"backH":0.62}', 0, 1, 11);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (12, 'youth-classic-tee', 'Youth Classic Tee', 'RT2000B', 1, 'tee', 'customizable', 'The classic tee scaled down for kids'' sizes.', 'The same cotton body as our classic tee, cut for youth sizing. A dependable choice for school groups, teams and family runs.', '100% cotton, 5.3 oz, youth fit', 8.75, NULL, 4, '{"frontW":0.4,"frontH":0.46,"backW":0.56,"backH":0.6}', 0, 1, 12);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (13, 'v-neck-tee', 'V-Neck Tee', '3005', 1, 'tee', 'customizable', 'A classic V-neck with a clean, covered collar.', 'A ring-spun cotton V-neck with a narrow, covered collar that keeps its shape. A softer alternative to a crew neck for retail-style designs.', '100% ring-spun cotton, 4.3 oz', 11, NULL, 4.5, '{"frontW":0.42,"frontH":0.5,"backW":0.62,"backH":0.66}', 0, 1, 13);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (14, 'long-sleeve-tee', 'Long Sleeve Tee', '3200', 1, 'longsleeve', 'customizable', 'A long-sleeve tee ready for your front and back design.', 'Make this long-sleeve tee yours with a custom design on the front, back, or both.', '100% ring-spun cotton, 4.5 oz, long sleeve', 15, NULL, 5.5, '{"frontW":0.4,"frontH":0.46,"backW":0.6,"backH":0.64}', 0, 1, 14);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (15, 'classic-pique-polo', 'Classic Piqué Polo', 'KCP-P100', 2, 'polo', 'customizable', 'A neat collared shirt for teams, workwear and everyday custom graphics.', 'A classic short-sleeve polo silhouette with a structured collar and a smooth area for a chest mark or larger back design. Choose a color and build your own front or back print in the studio.', 'Short-sleeve piqué knit with a two-button collar', 18, NULL, 5, '{"frontW":0.44,"frontH":0.48,"backW":0.56,"backH":0.6}', 1, 1, 14);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (16, 'premium-pullover-hoodie', 'Premium Pullover Hoodie', 'KCP-H100', 3, 'hoodie', 'customizable', 'A substantial fleece hoodie with a smooth face for crisp front and back prints.', 'A dependable everyday hoodie with a lined hood, ribbed cuffs and a roomy kangaroo pocket. The smooth face keeps large artwork clean while the fleece interior stays comfortable for daily wear.', '80/20 cotton-poly fleece, 8.0 oz, unisex fit', 28, NULL, 6, '{"frontW":0.46,"frontH":0.42,"backW":0.58,"backH":0.58}', 1, 1, 15);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (17, 'heavyweight-crewneck', 'Heavyweight Crewneck', 'KCP-C100', 3, 'crew', 'customizable', 'A clean crewneck silhouette with a wide, reliable print surface.', 'The no-hood layer for uniforms, campus groups and retail collections. Ribbed trim holds its shape while the substantial fleece body gives artwork a stable, premium surface.', '80/20 cotton-poly fleece, 8.0 oz, unisex fit', 24, NULL, 6, '{"frontW":0.46,"frontH":0.44,"backW":0.58,"backH":0.6}', 1, 1, 16);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (18, 'five-panel-cap', 'Five-Panel Trucker Cap', '112FP', 4, 'cap', 'customizable', 'A structured front panel for compact marks, team identities and small artwork.', 'A five-panel trucker cap with a seamless front, curved brim, mesh back and adjustable snapback closure.', 'Cotton-polyester front with mesh back and adjustable snapback', 16, NULL, 4, '{"frontW":0.58,"frontH":0.3,"backW":0.5,"backH":0.22}', 0, 1, 17);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (19, 'canvas-tote', 'Canvas Tote', 'KCP-TOTE1', 4, 'tote', 'customizable', 'A sturdy reusable tote with room for bold front artwork and event marks.', 'A practical canvas carryall for markets, events and everyday brand visibility. The broad front panel gives artwork plenty of breathing room and the reinforced handles are built for repeat use.', '12 oz cotton canvas, reinforced handles', 14, NULL, 4, '{"frontW":0.52,"frontH":0.58,"backW":0.52,"backH":0.58}', 0, 1, 18);
INSERT INTO products (id, slug, name, style_code, category_id, kind, sale_mode, blurb, description, material, base_price, compare_at, print_fee_per_side, print_area, featured, active, sort_order) VALUES (20, 'ceramic-mug', 'Ceramic Mug', 'KCP-MUG1', 4, 'mug', 'customizable', 'A classic ceramic mug for logos, team marks and small-run gifts.', 'A dependable 11 oz ceramic mug with a smooth printable panel and a comfortable handle. A simple way to carry a brand into offices, studios and customer gift packs.', '11 oz glossy ceramic, dishwasher-safe finish', 12, NULL, 4, '{"frontW":0.6,"frontH":0.42,"backW":0.6,"backH":0.42}', 0, 1, 19);
